# ---------------------------------------------------------------- a-roi
sid = "a-roi"
S.append(SUBJ(sid, "Measuring Business Impact and ROI",
 "Budgets for AI renew on evidence. A baseline, a credible comparison and a cost model turn 'users like it' into a business case.",
 "ROI starts before the build: capture a baseline of the metric you'll move (handle time, resolution rate, cycle time, error rate) and its current cost. After launch, compare against that baseline credibly: ideally with a randomized holdout or A/B test, otherwise a staggered rollout or a matched comparison group, and be explicit about seasonality and other confounders. Value is translated into money (hours saved × loaded cost, revenue retained, errors avoided) and weighed against total cost of ownership: model and infrastructure spend, licences, people, integration and ongoing operations.\n\nReport ranges and guardrails (quality, CSAT, risk), not just a headline number.",
 "Build an ROI model and measurement plan for an AI support assistant: baseline from 8 weeks of ticket data, a 10% holdout design, value and TCO calculations, sensitivity analysis and a one-page executive readout.",
 [T(sid, "measure", "Baselines and credible comparisons",
   "Without a baseline, every number is an anecdote. Before launch, record the outcome metric and its variation over several weeks, plus guardrails such as CSAT, accuracy and escalation rate. The strongest comparison is a randomized holdout: a share of users or tickets stays without AI, so seasonality affects both groups equally. If that isn't possible, use a staggered rollout (teams switch on at different times) or a difference-in-differences comparison against similar teams. Run long enough to cover weekly cycles and novelty effects, and report confidence intervals. Measure outcomes, not usage; usage is an input.",
   [("Baseline before launch", "Several weeks of the target and guardrail metrics, with their natural variance."),
    ("Randomized holdout or A/B", "Keep a control group without AI so trends and seasonality cancel out."),
    ("Staggered rollout and diff-in-diff", "When randomization isn't possible, compare changes against similar untreated teams."),
    ("Confidence intervals and duration", "Cover weekly cycles and novelty effects; report uncertainty, not just point estimates.")]),
  T(sid, "model", "Value, total cost and the business case",
   "Translate measured effects into money with explicit assumptions. Time saved × volume × loaded hourly cost gives capacity value; be honest about whether capacity is redeployed or actually reduces cost. Add revenue effects (conversion, retention) and avoided costs (errors, penalties) only with evidence. On the cost side, include model and API spend, infrastructure, vendor licences, build and integration effort, and ongoing run costs (evals, monitoring, support and content upkeep). Compute payback period and ROI, then run a sensitivity analysis on the two or three assumptions that matter most. Present a range and the guardrail metrics alongside the headline.",
   [("Value translation", "Hours saved × loaded cost, revenue retained and errors avoided, each with a stated assumption."),
    ("Total cost of ownership", "Tokens, infrastructure, licences, build, integration and ongoing operations."),
    ("Payback and ROI", "Payback months = upfront cost ÷ monthly net benefit; ROI = (benefit − cost) ÷ cost."),
    ("Sensitivity and guardrails", "Show how ROI moves with key assumptions, and report quality and risk metrics with it.")])],
 [Q("Handle time fell 15% after launch, but it also fell in a team without the tool. What does this suggest?", ["Part of the drop is a trend or seasonal effect; compare against the control", "The AI caused the full 15%", "The data is wrong", "Stop measuring"], 0, "Control groups separate the AI's effect from background change."),
  Q("Which is an outcome metric rather than an input?", ["Average handle time per ticket", "Number of prompts sent", "Daily active users", "Tokens consumed"], 0, "Usage and tokens are inputs; outcomes are what the business pays for."),
  Q("Monthly net benefit is $40k and upfront cost is $200k. Payback period?", ["5 months", "2 months", "8 months", "40 months"], 0, "200,000 ÷ 40,000 = 5.")],
 [R("Trustworthy Online Controlled Experiments (Kohavi, Tang, Xu)", "https://experimentguide.com/", "book", "advanced", "The practical guide to A/B tests and holdouts from experimentation leaders at Microsoft, Google and LinkedIn: metrics, pitfalls and trustworthy analysis."),
  R("GitHub: Quantifying Copilot's impact on developer productivity", "https://github.blog/news-insights/research/research-quantifying-github-copilots-impact-on-developer-productivity-and-happiness/", "case", "intro", "A randomized controlled experiment with 95 developers showing a 55% faster task completion with a confidence interval. A model for credible AI impact measurement."),
  R("FinOps Foundation: FinOps for AI", "https://www.finops.org/wg/finops-for-ai-overview/", "guide", "intermediate", "How to manage AI costs and tokenomics, allocate spend and build unit economics, which are the cost side of the ROI model."),
  R("Klarna: AI assistant handles two-thirds of customer service chats", "https://www.klarna.com/international/press/klarna-ai-assistant-handles-two-thirds-of-customer-service-chats-in-its-first-month/", "case", "intro", "Company-reported before/after metrics (resolution time, repeat inquiries, estimated profit impact). A useful example of the metrics an ROI readout uses.")],
 dict(intuition="ROI is a before-and-after photo taken from the same angle, in the same light. The baseline is the 'before'. A control group makes sure the light didn't just change on its own. The cost model is the price tag. Executives trust the photo only if you show both pictures, how you took them, and the price.",
  how=["Capture a multi-week baseline of outcome and guardrail metrics.", "Design the comparison: randomized holdout, staggered rollout or diff-in-diff.", "Measure outcomes over enough time and report confidence intervals.", "Translate effects into money with explicit assumptions; build total cost of ownership.", "Compute payback and ROI, run sensitivity analysis, and present a range plus guardrails."],
  example="Baseline: 42,000 tickets/month, 9.5 min average handle time, $38/hour loaded cost. With a 10% holdout over 8 weeks, AI-assisted tickets average 7.6 min versus 9.4 min in the holdout, a 1.8-minute (19%) effect, with a 95% CI of 1.4–2.2 min. Value: 37,800 assisted tickets × 1.8 min = 1,134 hours ≈ $43,100/month. Costs: $6,000/month for tokens and infrastructure plus $4,000/month to operate, so net ≈ $33,100/month. With $180k upfront, payback is about 5.4 months.",
  lang="python",
  code='''import random, statistics, math
# Holdout-based effect estimate with a bootstrap CI, then value, TCO, payback and a sensitivity table.
rng = random.Random(42)
holdout = [max(1, rng.gauss(9.4, 3.0)) for _ in range(4_200)]     # minutes, tickets without AI
treated = [max(1, rng.gauss(7.6, 3.0)) for _ in range(37_800)]    # minutes, AI-assisted tickets
effect = statistics.mean(holdout) - statistics.mean(treated)
boots = sorted(statistics.mean(rng.choices(holdout, k=800)) - statistics.mean(rng.choices(treated, k=800)) for _ in range(2000))
lo, hi = boots[50], boots[1949]
print(f"effect {effect:.2f} min/ticket (95% CI ~{lo:.2f}-{hi:.2f})")
def roi(effect_min, tickets=37_800, loaded_hr=38.0, run_cost=10_000, upfront=180_000):
    value = tickets * effect_min / 60 * loaded_hr
    net = value - run_cost
    payback = upfront / net if net > 0 else math.inf
    return value, net, payback
v, net, pb = roi(effect)
print(f"value ${v:,.0f}/mo, net ${net:,.0f}/mo, payback {pb:.1f} months")
print("sensitivity (effect min -> payback months):")
for e in (lo, effect, hi):
    print(f"  {e:.2f} -> {roi(e)[2]:.1f}")''',
  mistakes=["No baseline before launch.", "Attributing all improvement to AI without a control group.", "Reporting usage (prompts, DAU) as impact.", "Leaving ongoing run and people costs out of TCO."],
  enterprise="A telecom's steering committee had rejected two AI business cases built on vendor benchmarks. The third team ran a 10% randomized holdout for 8 weeks, reported a handle-time effect with confidence intervals, full TCO and a sensitivity table, and got approval to scale to all regions.",
  takeaways=["Baseline first; no baseline, no ROI.", "Use holdouts or staggered rollouts to isolate the AI's effect.", "Measure outcomes, not usage.", "Present value, full TCO, payback, sensitivity and guardrails together."],
  diagram='flowchart LR\n  BL["Baseline (weeks before launch)"] --> EXP{"Comparison design"}\n  EXP --> HO["Randomized holdout"]\n  EXP --> ST["Staggered rollout / diff-in-diff"]\n  HO --> EF["Effect + confidence interval"]\n  ST --> EF\n  EF --> VAL["Value: hours x cost, revenue, errors avoided"]\n  TCO["TCO: tokens, infra, licences, build, ops"] --> ROI["ROI, payback, sensitivity"]\n  VAL --> ROI\n  ROI --> RD["Exec readout with guardrails"]',
  diagramAlt="A baseline captured before launch feeds a comparison design, either a randomized holdout or a staggered rollout with difference-in-differences, producing an effect with a confidence interval. The effect becomes value, which combines with total cost of ownership into ROI, payback and sensitivity, presented in an executive readout with guardrail metrics."),
 case=C("Klarna", "Klarna AI assistant handles two-thirds of customer service chats in its first month (press release, Feb 2024)", "https://www.klarna.com/international/press/klarna-ai-assistant-handles-two-thirds-of-customer-service-chats-in-its-first-month/",
   "Klarna reported its AI assistant's first-month impact against its prior human baseline: 2.3 million conversations (two-thirds of customer service chats), work it equated to 700 full-time agents, customer satisfaction on par with human agents, a 25% drop in repeat inquiries, and errands resolved in under 2 minutes versus 11 before. It estimated a $40 million profit improvement in 2024.",
   "An ROI readout pairs volume and speed gains with quality guardrails (satisfaction, repeat contacts) and a money estimate. Treat company-reported figures as claims and build your own controlled measurement.")))
